                              <tr>
                                <th className="px-6 py-5">날짜 / 구분</th>
                                <th className="px-6 py-5">수량</th>
                                {item.type === 'part' && <th className="px-6 py-5">기종</th>}
                                {item.type === 'product' && (
                                  <>
                                    <th className="px-6 py-5">일련번호</th>
                                    <th className="px-6 py-5">대상자</th>
                                    <th className="px-6 py-5">주소</th>
                                  </>
                                )}
                                <th className="px-6 py-5">비고</th>
                                <th className="px-6 py-5 text-center">작업</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y-2 divide-white">
                                {filteredHistory.map(t => (
                                    <tr key={t.id} className={`hover:bg-white transition-all group ${editingTransactionId === t.id ? 'bg-indigo-50/50' : ''}`}>
                                        <td className="px-6 py-6">
                                          <div className="flex items-center gap-4">
                                            <div className={`p-2 rounded-xl ${t.type === 'purchase' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                              {t.type === 'purchase' ? <ArrowUpIcon className="w-5 h-5"/> : <ArrowDownIcon className="w-5 h-5"/>}
                                            </div>
                                            <div>
                                              <p className="font-black text-slate-700 text-lg">{new Date(t.date).toLocaleDateString()}</p>
                                              <p className="text-xs text-slate-400 font-bold">{new Date(t.date).toLocaleTimeString()}</p>
                                            </div>
                                          </div>
                                        </td>
                                        <td className="px-6 py-6">
                                          {editingTransactionId === t.id ? (
                                            <input name="quantity" type="number" value={transEditData.quantity} onChange={handleTransEditChange} className="w-24 px-3 py-2 border-2 rounded-xl bg-white font-black text-lg" />
                                          ) : (
                                            <span className={`font-black text-2xl ${t.type === 'purchase' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                              {t.type === 'purchase' ? '+' : '-'}{t.quantity.toLocaleString()}
                                            </span>
                                          )}
                                        </td>
                                        {item.type === 'part' && (
                                          <td className="px-6 py-6">
                                            {editingTransactionId === t.id ? (
                                              <input name="modelName" value={transEditData.modelName || ''} onChange={handleTransEditChange} className="w-32 px-3 py-2 border-2 rounded-xl bg-white" />
                                            ) : (
                                              <span className="font-black text-slate-600">{t.modelName || '-'}</span>
                                            )}
                                          </td>
                                        )}
                                        {item.type === 'product' && (
                                          <>
                                            <td className="px-6 py-6">
                                              {editingTransactionId === t.id ? (
                                                <input name="serialNumber" value={transEditData.serialNumber || ''} onChange={handleTransEditChange} className="w-32 px-3 py-2 border-2 rounded-xl bg-white font-black uppercase" />
                                              ) : (
                                                <span className="font-mono font-black text-indigo-600 text-lg">{t.serialNumber || '-'}</span>
                                              )}
                                            </td>
                                            <td className="px-6 py-6">
                                              {editingTransactionId === t.id ? (
                                                <div className="space-y-2">
                                                  <input name="customerName" value={transEditData.customerName || ''} onChange={handleTransEditChange} placeholder="이름" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />
                                                  <input name="phoneNumber" value={transEditData.phoneNumber || ''} onChange={handleTransEditChange} placeholder="번호" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />
                                                </div>
                                              ) : (
                                                <>
                                                  <p className="font-black text-slate-800 text-lg">{t.customerName || '-'}</p>
                                                  <p className="text-slate-400 font-bold text-sm">{t.phoneNumber || '-'}</p>
                                                </>
                                              )}
                                            </td>
                                            <td className="px-6 py-6">
                                              {editingTransactionId === t.id ? (
                                                <input name="address" value={transEditData.address || ''} onChange={handleTransEditChange} placeholder="주소" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />
                                              ) : (
                                                <p className="text-slate-500 font-bold truncate max-w-[200px]" title={t.address}>{t.address || '-'}</p>
                                              )}
                                            </td>
                                          </>
                                        )}
                                        <td className="px-6 py-6">
                                          {editingTransactionId === t.id ? (
                                            <input name="remarks" value={transEditData.remarks || ''} onChange={handleTransEditChange} placeholder="비고" className="w-full px-3 py-2 border-2 rounded-xl bg-white" />
                                          ) : (
                                            <p className="text-sm text-slate-400 font-black truncate max-w-[250px]">{t.remarks || '-'}</p>
                                          )}
                                        </td>
                                        <td className="px-6 py-6 text-center">
                                          <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            {editingTransactionId === t.id ? (
                                              <>
                                                <button onClick={() => handleSaveTransEdit(t.id)} className="p-3 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all"><CheckIcon className="w-6 h-6" /></button>
                                                <button onClick={() => setEditingTransactionId(null)} className="p-3 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><CloseIcon className="w-6 h-6" /></button>
                                              </>
                                            ) : (
                                              <>
                                                <button onClick={() => handleEditTransaction(t)} className="p-3 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"><EditIcon className="w-6 h-6" /></button>
                                                <button onClick={() => handleDeleteTrans(t.id)} className="p-3 text-rose-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"><TrashIcon className="w-6 h-6" /></button>
                                              </>
                                            )}
                                          </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table></div>
                    )}
                </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ItemDetailModal;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import type { Item, Transaction } from './types';
import AddItemModal from './components/AddItemModal';
import ItemDetailModal from './components/ItemDetailModal';
import { PlusIcon, BoxIcon, SearchIcon, TrashIcon, DownloadIcon, CloudIcon, ServerIcon, SyncIcon } from './components/icons';

const STORAGE_KEY = 'inventory_system_data_v2';
const ADMIN_PASSWORD = '5200';
const PRODUCT_ONLY_PASSWORD = '3281';

const generateId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

const calculateStock = (item: Item): number => {
  return item.transactions.reduce((acc, t) => {
    return t.type === 'purchase' ? acc + t.quantity : acc - t.quantity;
  }, 0);
};

const App: React.FC = () => {
  const [authRole, setAuthRole] = useState<'admin' | 'product_only' | null>(null);
  const [loginPassword, setLoginPassword] = useState('');
  const [activeTab, setActiveTab] = useState<'part' | 'product'>('part');

  const [items, setItems] = useState<Item[]>([]);
  const [showAddItemModal, setShowAddItemModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<{id: string, type: 'inventory'} | null>(null);
  const [deletePassword, setDeletePassword] = useState('');

  // Sync States
  const [syncStatus, setSyncStatus] = useState<'idle' | 'loading' | 'success' | 'error' | 'offline'>('loading');
  const [lastSyncedAt, setLastSyncedAt] = useState<Date | null>(null);
  const [dataSource, setDataSource] = useState<'cloud' | 'local'>('local');
  const isInitialLoad = useRef(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Cloud DB Fetch
  const fetchFromCloud = async () => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory');
      if (!response.ok) throw new Error('Server unreachable');

      const data = await response.json();
      if (data && Array.isArray(data.items)) {
        setItems(data.items);
        setDataSource('cloud');
        setSyncStatus('success');
        setLastSyncedAt(new Date());
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data.items));
        return true;
      }
    } catch (err) {
      console.warn('Cloud fetch failed, using local cache:', err);
      const savedItems = localStorage.getItem(STORAGE_KEY);
      if (savedItems) {
        setItems(JSON.parse(savedItems));
      }
      setDataSource('local');
      setSyncStatus('offline');
      return false;
    }
  };

  // Cloud DB Save
  const saveToCloud = async (data: Item[]) => {
    setSyncStatus('loading');
    try {
      const response = await fetch('/api/inventory', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          items: data,
          lastUpdated: new Date().toISOString()
        })
      });

      if (response.ok) {
        setSyncStatus('success');
        setLastSyncedAt(new Date());
        setDataSource('cloud');
      } else {
        throw new Error('Save failed');
      }
    } catch (err) {
      console.error('Cloud Save Error:', err);
      setSyncStatus('error');
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }
  };

  // Initial Data Load
  useEffect(() => {
    fetchFromCloud().finally(() => {
      isInitialLoad.current = false;
    });
  }, []);

  // Auto-Save Effect (Debounced)
  useEffect(() => {
    if (isInitialLoad.current) return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
    const timer = setTimeout(() => {
      saveToCloud(items);
    }, 1500);
    return () => clearTimeout(timer);
  }, [items]);

  const stats = useMemo(() => {
    return {
      partCount: items.filter(i => i.type === 'part').length,
      productCount: items.filter(i => i.type === 'product').length,
    };
  }, [items]);

  const allUsedSerials = useMemo(() => {
    const serials: string[] = [];
    items.forEach(item => {
      item.transactions.forEach(t => {
        if (t.serialNumber) serials.push(t.serialNumber.toUpperCase());
      });
    });
    return Array.from(new Set(serials));
  }, [items]);

  // Local Import / Export Logic
  const handleLocalExport = () => {
    const dataObj = { items, exportDate: new Date().toISOString(), version: '2.0' };
    const blob = new Blob([JSON.stringify(dataObj, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `INVENTORY_BACKUP_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLocalImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.items && Array.isArray(json.items)) {
          if (confirm('백업 파일을 불러오시겠습니까? 현재 클라우드와 로컬 데이터가 이 파일로 덮어씌워집니다.')) {
            setItems(json.items);
            alert('데이터 복구 완료. 클라우드 동기화가 진행됩니다.');
          }
        } else {
          alert('올바른 백업 파일 형식이 아닙니다.');
        }
      } catch (err) {
        alert('파일을 읽는 중 오류가 발생했습니다.');
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (loginPassword === ADMIN_PASSWORD) setAuthRole('admin');
    else if (loginPassword === PRODUCT_ONLY_PASSWORD) setAuthRole('product_only');
    else alert('비밀번호가 틀렸습니다.');
    setLoginPassword('');
  };

  const handleLogout = () => {
    setAuthRole(null);
    setSearchTerm('');
  };

  const handleAddItem = (itemData: Omit<Item, 'id' | 'transactions'>, initialQuantity: number) => {
    const newItem: Item = { ...itemData, id: generateId('item'), transactions: [] };
    if (initialQuantity > 0) {
      newItem.transactions.push({
        id: generateId('t'), type: 'purchase', quantity: initialQuantity,
        date: new Date().toISOString(), remarks: '초기 수량 등록',
      });
    }
    setItems(prev => {
      const newItems = [...prev, newItem];
      // Alphanumeric sorting by code
      return newItems.sort((a, b) => a.code.localeCompare(b.code, undefined, { numeric: true, sensitivity: 'base' }));
    });
  };

  const handleDeleteItemConfirm = () => {
    const currentPass = authRole === 'admin' ? ADMIN_PASSWORD : PRODUCT_ONLY_PASSWORD;
    if (deletePassword !== currentPass) {
      alert('비밀번호가 틀렸습니다.');
      return;
    }
    if (itemToDelete) {
      setItems(prev => prev.filter(i => i.id !== itemToDelete.id));
      setItemToDelete(null);
      setDeletePassword('');
    }
  };

  const handleUpdateItem = (itemId: string, updatedData: Partial<Item>) => {
    setItems(prev => prev.map(item => item.id === itemId ? { ...item, ...updatedData } : item));
  };

  const handleAddTransaction = (itemId: string, transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = { ...transaction, id: generateId('t') };
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: [...item.transactions, newTransaction] };
      }
      return item;
    }));
  };

  const handleUpdateTransaction = (itemId: string, transactionId: string, updatedData: Partial<Transaction>) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.map(t => t.id === transactionId ? { ...t, ...updatedData } : t) };
      }
      return item;
    }));
  };

  const handleDeleteTransaction = (itemId: string, transactionId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id === itemId) {
        return { ...item, transactions: item.transactions.filter(t => t.id !== transactionId) };
      }
      return item;
    }));
  };

  const selectedItem = useMemo(() => items.find(i => i.id === selectedItemId), [items, selectedItemId]);

  const filteredInventory = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    return items.filter(item => {
        const matchesTab = (activeTab === 'part' && item.type === 'part') || (activeTab === 'product' && item.type === 'product');
        if (!matchesTab) return false;
        const basicMatch = item.name.toLowerCase().includes(term) || item.code.toLowerCase().includes(term);
        if (basicMatch) return true;
        if (activeTab === 'product') return item.transactions.some(t => t.serialNumber?.toLowerCase().includes(term));
        return false;
    });
  }, [items, searchTerm, activeTab]);

  const exportToExcel = () => {
    let csvContent = "\ufeff";
    const headers = activeTab === 'part' ? ['코드', '품명', '도번', '현재재고'] : ['코드', '제품명', '현재재고'];
    csvContent += headers.join(',') + '\r\n';
    filteredInventory.forEach(item => {
      const row = activeTab === 'part' 
        ? [item.code, item.name, item.drawingNumber, calculateStock(item)]
        : [item.code, item.name, calculateStock(item)];
      csvContent += row.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',') + '\r\n';
    });
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${activeTab === 'part' ? '부품' : '제품'}_재고_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!authRole) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md p-8 sm:p-12 animate-fade-in-up border border-slate-100">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-indigo-600 p-4 rounded-2xl shadow-lg mb-6">
              <BoxIcon className="w-10 h-10 text-white" />
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight uppercase text-center">Ajin 재고 관리 시스템</h1>
            <p className="text-[10px] text-slate-400 font-black mt-2 tracking-widest uppercase">Vercel KV Cloud Infrastructure</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" autoFocus value={loginPassword}
              onChange={(e) => setLoginPassword(e.target.value)}
              placeholder="PASSWORD"
              className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-600 outline-none text-center text-3xl font-black tracking-[0.5em] transition-all"
            />
            <button type="submit" className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-xl hover:bg-indigo-700 transition-all text-lg uppercase tracking-widest">시스템 로그인</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-4 sm:px-6">
            <div className="flex justify-between items-center py-4">
                <div className="flex items-center space-x-4">
                    <BoxIcon className="h-8 w-8 text-indigo-600" />
                    <div>
                      <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase">Ajin 재고 관리 시스템</h1>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider ${dataSource === 'cloud' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-amber-50 text-amber-600 border border-amber-100'}`}>
                          {dataSource === 'cloud' ? <ServerIcon className="w-2.5 h-2.5" /> : <BoxIcon className="w-2.5 h-2.5" />}
                          {dataSource === 'cloud' ? 'Cloud Connected' : 'Local Backup Mode'}
                        </span>
                        {syncStatus === 'loading' && <SyncIcon className="w-3 h-3 text-indigo-400 animate-spin" />}
                        {syncStatus === 'error' && <span className="text-[9px] text-rose-500 font-black uppercase">Sync Failed</span>}
                        {lastSyncedAt && <span className="text-[9px] text-slate-400 font-bold ml-1">{lastSyncedAt.toLocaleTimeString()}</span>}
                      </div>
                    </div>
                </div>

                <div className="flex flex-col items-end space-y-2">
                  <div className="flex items-center space-x-2">
